from django.urls import path
from django.contrib.auth import views as auth
from bands import views as v
urlpatterns=[path('',v.discover,name='discover'),path('register/',v.register,name='register'),path('login/',auth.LoginView.as_view(template_name='bands/form.html',extra_context={'title':'Welcome back'}),name='login'),path('logout/',auth.LogoutView.as_view(),name='logout'),path('profile/',v.profile,name='profile'),path('my-bands/',v.my_bands,name='my_bands'),path('start/',v.band_form,name='create'),path('bands/<int:pk>/',v.band_detail,name='band'),path('bands/<int:pk>/edit/',v.band_form,name='edit'),path('bands/<int:pk>/workspace/',v.workspace,name='workspace'),path('bands/<int:pk>/leave/',v.leave,name='leave'),path('requests/<int:pk>/review/',v.review_request,name='review'),path('requests/<int:pk>/withdraw/',v.withdraw,name='withdraw'),path('help/',v.help_page,name='help'),path('account/delete/',v.delete_account,name='delete'),path('password-reset/',v.RecoveryView.as_view(),name='password_reset'),path('password-reset/sent/',auth.PasswordResetDoneView.as_view(template_name='bands/reset_done.html'),name='password_reset_done'),path('reset/<uidb64>/<token>/',auth.PasswordResetConfirmView.as_view(template_name='bands/form.html',extra_context={'title':'Choose a new password'}),name='password_reset_confirm'),path('reset/complete/',auth.PasswordResetCompleteView.as_view(template_name='bands/reset_complete.html'),name='password_reset_complete')]
